1	package netdiag
2	
3	import (
4		"fmt"
5		"strconv"
6		"time"
7	
8		"charm.land/lipgloss/v2"
9	
10		"github.com/anthnel/devdesk/internal/nettrace"
11		"github.com/anthnel/devdesk/internal/ui/components"
12		"github.com/anthnel/devdesk/internal/ui/datatable"
13		"github.com/anthnel/devdesk/internal/ui/shortcut"
14		"github.com/anthnel/devdesk/internal/ui/theme"
15	)
16	
17	// pathBarLabel prefixes the target field in the bar.
18	const pathBarLabel = "Target › "
19	
20	// pathColumns describes the hops table. Plain text in Cell, colour in Style
21	// (Rule 122). A silent hop is dim, never red: it is not a failure.
22	func pathColumns() []datatable.Column[nettrace.Hop] {
23		hop := datatable.Column[nettrace.Hop]{
24			Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
25			Cell: func(h nettrace.Hop) string { return strconv.Itoa(h.TTL) },
26		}
