	var wg sync.WaitGroup
	for i, c := range conns {
		ttl := i + 1
		var tctx context.Context
		tctx, cancels[ttl] = context.WithCancel(ctx)
		wg.Add(1)
		go func() {
			defer wg.Done()
			defer func() { _ = c.close() }()
			results <- probeOne(tctx, c, ttl, target, opts.ProbeTimeout)
		}()
	}

	t := newTally(n)
	// collectOne records an answer and streams it when it is a hop worth
	// showing: resolved, and not above the terminal TTL.
	collectOne := func(r probeResult) {
		t.add(r)
		if onHop == nil || !r.resolved {
			return
		}
		if term := t.terminal(); term > 0 && r.ttl > term {
			return
		}
		onHop(r.hop)
	}
	cutAbove := func() {
		if term := t.terminal(); term > 0 {
			for ttl := term + 1; ttl <= n; ttl++ {
				cancels[ttl]()
			}
		}
	}
collect:
	for !t.complete() {
		select {
		case r := <-results:
			collectOne(r)
			cutAbove()
		case <-ctx.Done():
			break collect
		}
	}
	for _, cancel := range cancels[1:] {
		cancel()
	}
	wg.Wait()
	close(results)
	for r := range results { // answers that landed while stopping
		collectOne(r)
	}

	if t.complete() {
		return t.result(target, start)
	}
	return endedEarly(ctx, target, t, n, start)
}

