68	func openAll(ctx context.Context, p prober, target netip.Addr, n int) ([]probeConn, error) {
69		conns := make([]probeConn, 0, n)
70		for ttl := 1; ttl <= n; ttl++ {
71			if err := ctx.Err(); err != nil {
72				closeAll(conns)
73				return nil, err
74			}
75			c, err := p.open(ctx, target, ttl)
76			if err != nil {
77				closeAll(conns)
78				return nil, err
79			}
80			conns = append(conns, c)
81		}
82		return conns, nil
83	}
