104	// probeAll runs phase 2: one goroutine per connection.
105	func probeAll(ctx context.Context, target netip.Addr, opts Options, conns []probeConn, start time.Time, onHop func(Hop)) Result {
106		n := len(conns)
107		results := make(chan probeResult, n)
108		cancels := make([]context.CancelFunc, n+1) // indexed by TTL
109		var wg sync.WaitGroup
110		for i, c := range conns {
111			ttl := i + 1
112			var tctx context.Context
113			tctx, cancels[ttl] = context.WithCancel(ctx)
114			wg.Add(1)
115			go func() {
116				defer wg.Done()
117				defer func() { _ = c.close() }()
118				results <- probeOne(tctx, c, ttl, target, opts.ProbeTimeout)
119			}()
120		}
121	
122		t := newTally(n)
123		// collectOne records an answer and streams it when it is a hop worth
124		// showing: resolved, and not above the terminal TTL.
125		collectOne := func(r probeResult) {
126			t.add(r)
127			if onHop == nil || !r.resolved {
128				return
129			}
130			if term := t.terminal(); term > 0 && r.ttl > term {
131				return
132			}
133			onHop(r.hop)
134		}
135		cutAbove := func() {
136			if term := t.terminal(); term > 0 {
137				for ttl := term + 1; ttl <= n; ttl++ {
138					cancels[ttl]()
139				}
140			}
141		}
142	collect:
143		for !t.complete() {
144			select {
145			case r := <-results:
146				collectOne(r)
147				cutAbove()
148			case <-ctx.Done():
149				break collect
150			}
151		}
152		for _, cancel := range cancels[1:] {
153			cancel()
154		}
155		wg.Wait()
156		close(results)
157		for r := range results { // answers that landed while stopping
158			collectOne(r)
159		}
160	
161		if t.complete() {
162			return t.result(target, start)
163		}
164		return endedEarly(ctx, target, t, n, start)
165	}
